with d as (select value r from jsonb_array_elements($q$[{"slug":"soft-tofu-stew","title":"Soft Tofu Stew (Sundubu-jjigae)","cuisine":"korean","meal_types":["dinner"],"diets":["no-dairy"],"difficulty":"easy","total_minutes":30,"recipe":{"id":"soft-tofu-stew","title":"Soft Tofu Stew (Sundubu-jjigae)","summary":"A bubbling, spicy Korean stew of silken tofu, kimchi and pork, finished with an egg.","cuisine":"korean","diets":["no-dairy"],"mealTypes":["dinner"],"difficulty":"easy","prepMinutes":10,"cookMinutes":20,"servings":4,"onePot":true,"seasons":["autumn","winter"],"ingredientGroups":[{"items":[{"item":"sesame oil","raw":"1 tbsp sesame oil","quantity":1,"unit":"tbsp","ingredientId":"sesame-oil"},{"item":"pork mince","raw":"150g pork mince","quantity":150,"unit":"g","ingredientId":"pork-mince"},{"item":"brown onion","raw":"1/2 brown onion, diced","quantity":0.5,"ingredientId":"brown-onion","prep":"diced"},{"item":"garlic","raw":"3 garlic cloves, crushed","quantity":3,"unit":"clove","ingredientId":"garlic","prep":"crushed"},{"item":"gochugaru","raw":"2 tbsp gochugaru","quantity":2,"unit":"tbsp","ingredientId":"gochugaru"},{"item":"kimchi","raw":"150g kimchi, chopped","quantity":150,"unit":"g","ingredientId":"kimchi","prep":"chopped"},{"item":"soy sauce","raw":"1 tbsp soy sauce","quantity":1,"unit":"tbsp","ingredientId":"soy-sauce"},{"item":"fish sauce","raw":"1 tsp fish sauce","quantity":1,"unit":"tsp","ingredientId":"fish-sauce"},{"item":"dashi","raw":"750ml dashi (made from instant dashi powder)","quantity":750,"unit":"ml","ingredientId":"dashi","note":"made from instant dashi powder"},{"item":"zucchini","raw":"1 zucchini, halved and sliced","quantity":1,"ingredientId":"zucchini","prep":"halved and sliced"},{"item":"silken tofu","raw":"600g silken tofu","quantity":600,"unit":"g","ingredientId":"silken-tofu"},{"item":"eggs","raw":"4 eggs","quantity":4,"ingredientId":"egg"},{"item":"spring onions","raw":"2 spring onions, sliced","quantity":2,"ingredientId":"spring-onion","prep":"sliced"}]},{"title":"To serve","items":[{"item":"Steamed short-grain rice","raw":"Steamed short-grain rice","ingredientId":"sushi-rice"}]}],"steps":[{"text":"Heat the sesame oil in a medium heavy pot over medium heat. Cook the pork mince for 4 minutes, breaking it up, until browned and cooked through. Add the onion and garlic for 2 minutes."},{"text":"Stir in the gochugaru for 30 seconds, then the kimchi for 2 minutes."},{"text":"Add the soy sauce, fish sauce and dashi and bring to the boil. Add the zucchini and simmer for 4 minutes."},{"text":"Spoon the tofu into the pot in large pieces and simmer gently for 3 minutes; it's fragile, so don't stir hard."},{"text":"Crack the eggs into the bubbling stew, cover and simmer for 3 to 4 minutes, until the whites are set. Scatter with spring onion and serve bubbling hot with rice."}],"notes":["The yolks are soft after 3 to 4 minutes. For pregnant people, young children, older people or anyone with a weakened immune system, simmer until firm, about 6 minutes, or stir the eggs through.","Gochugaru (Korean chilli flakes) is fruity rather than fierce. Start with 1 tbsp if you're unsure.","Food safety: Cook mince and sausages until no pink remains and the centre reaches 75°C. Raw and lightly cooked foods aren't recommended for pregnant women, young children, older people or anyone with a weakened immune system."],"source":"user","provenance":"ai-draft"}},{"slug":"mee-goreng","title":"Mee Goreng","cuisine":"malaysian","meal_types":["dinner","lunch"],"diets":["no-dairy"],"difficulty":"easy","total_minutes":30,"recipe":{"id":"mee-goreng","title":"Mee Goreng","summary":"Malaysian hawker-style fried noodles with chicken, egg and greens in a sweet, spicy sauce.","cuisine":"malaysian","diets":["no-dairy"],"mealTypes":["dinner","lunch"],"difficulty":"easy","prepMinutes":15,"cookMinutes":15,"servings":4,"onePot":false,"ingredientGroups":[{"title":"Sauce","items":[{"item":"kecap manis","raw":"3 tbsp kecap manis","quantity":3,"unit":"tbsp","ingredientId":"kecap-manis"},{"item":"tomato sauce","raw":"2 tbsp tomato sauce","quantity":2,"unit":"tbsp","ingredientId":"tomato-sauce"},{"item":"soy sauce","raw":"1 tbsp soy sauce","quantity":1,"unit":"tbsp","ingredientId":"soy-sauce"},{"item":"sambal oelek","raw":"1-2 tbsp sambal oelek","quantity":{"min":1,"max":2},"unit":"tbsp","ingredientId":"sambal-oelek"},{"item":"sugar","raw":"1 tsp sugar","quantity":1,"unit":"tsp","ingredientId":"sugar"}]},{"title":"Noodles","items":[{"item":"fresh hokkien noodles","raw":"600g fresh hokkien noodles","quantity":600,"unit":"g","ingredientId":"hokkien-noodles"},{"item":"neutral oil","raw":"3 tbsp neutral oil","quantity":3,"unit":"tbsp","ingredientId":"neutral-oil"},{"item":"chicken thigh fillets","raw":"400g chicken thigh fillets, thinly sliced","quantity":400,"unit":"g","ingredientId":"chicken-thigh","prep":"thinly sliced"},{"item":"garlic","raw":"3 garlic cloves, finely chopped","quantity":3,"unit":"clove","ingredientId":"garlic","prep":"finely chopped"},{"item":"shallots","raw":"2 shallots, sliced","quantity":2,"ingredientId":"shallot","prep":"sliced"},{"item":"eggs","raw":"2 eggs, beaten","quantity":2,"ingredientId":"egg","prep":"beaten"},{"item":"bok choy","raw":"1 bunch bok choy, chopped","quantity":1,"unit":"bunch","ingredientId":"bok-choy","prep":"chopped"},{"item":"bean sprouts","raw":"150g bean sprouts","quantity":150,"unit":"g","ingredientId":"bean-sprouts"},{"item":"tomatoes","raw":"2 tomatoes, cut into wedges","quantity":2,"ingredientId":"tomato","prep":"cut into wedges"}]},{"title":"To serve","items":[{"item":"fried shallots","raw":"2 tbsp fried shallots","quantity":2,"unit":"tbsp","ingredientId":"fried-shallots"},{"item":"Lime wedges","raw":"Lime wedges","ingredientId":"lime"}]}],"steps":[{"text":"Mix the sauce ingredients. Loosen the noodles by pouring boiling water over them in a colander, then separate gently with tongs and drain well."},{"text":"Heat 1 tbsp oil in a wok over high heat. Stir-fry the chicken for 4 to 5 minutes until cooked through. Lift onto a plate."},{"text":"Add another 1 tbsp oil, then the garlic and shallot for 30 seconds. Push them to one side, pour the eggs into the space and scramble until just set."},{"text":"Add the rest of the oil, the noodles and the sauce. Toss over high heat for 2 minutes, until the noodles are coated and starting to char."},{"text":"Add the chicken, bok choy, bean sprouts and tomato and toss for 2 minutes more, until the greens wilt. Serve topped with fried shallots, with lime wedges to squeeze over."}],"notes":["Prawns, fried tofu or leftover roast chicken all work in place of the chicken.","Hokkien noodles are wheat noodles, so this isn't gluten-free.","Food safety: Cook chicken and other poultry until the juices run clear and the thickest part reaches 75°C."],"source":"user","provenance":"ai-draft"}},{"slug":"chicken-tinola","title":"Chicken Tinola","cuisine":"filipino","meal_types":["dinner","lunch"],"diets":["no-gluten","no-dairy"],"difficulty":"easy","total_minutes":60,"recipe":{"id":"chicken-tinola","title":"Chicken Tinola","summary":"Filipino comfort soup of chicken simmered in a clear, gingery broth with papaya and greens.","cuisine":"filipino","diets":["no-gluten","no-dairy"],"mealTypes":["dinner","lunch"],"difficulty":"easy","prepMinutes":15,"cookMinutes":45,"servings":4,"onePot":true,"seasons":["autumn","winter"],"ingredientGroups":[{"items":[{"item":"neutral oil","raw":"2 tbsp neutral oil","quantity":2,"unit":"tbsp","ingredientId":"neutral-oil"},{"item":"brown onion","raw":"1 brown onion, sliced","quantity":1,"ingredientId":"brown-onion","prep":"sliced"},{"item":"garlic","raw":"4 garlic cloves, crushed","quantity":4,"unit":"clove","ingredientId":"garlic","prep":"crushed"},{"item":"piece ginger","raw":"6cm piece ginger, peeled and cut into thin strips","quantity":6,"unit":"cm","ingredientId":"ginger","prep":"peeled and cut into thin strips"},{"item":"bone-in chicken pieces","raw":"1.2kg bone-in chicken pieces (drumsticks and thighs)","quantity":1.2,"unit":"kg","ingredientId":"chicken-pieces","note":"drumsticks and thighs"},{"item":"fish sauce","raw":"2 tbsp fish sauce","quantity":2,"unit":"tbsp","ingredientId":"fish-sauce"},{"item":"water","raw":"1.25L water","quantity":1.25,"unit":"l","ingredientId":"water"},{"item":"small green papaya","raw":"1 small green papaya (or 2 zucchini), peeled, seeded and cut into wedges","quantity":1,"ingredientId":"green-papaya","prep":"peeled, seeded and cut into wedges","note":"or 2 zucchini"},{"item":"baby spinach","raw":"100g baby spinach","quantity":100,"unit":"g","ingredientId":"baby-spinach"},{"item":"black pepper","raw":"1/2 tsp black pepper","quantity":0.5,"unit":"tsp","ingredientId":"black-pepper"}]},{"title":"To serve","items":[{"item":"Steamed jasmine rice","raw":"Steamed jasmine rice","ingredientId":"jasmine-rice"},{"item":"Fish sauce","raw":"Fish sauce","ingredientId":"fish-sauce"},{"item":"Lime wedges","raw":"Lime wedges","ingredientId":"lime"}]}],"steps":[{"text":"Heat the oil in a large pot over medium heat. Cook the onion, garlic and ginger for 4 minutes until fragrant and soft."},{"text":"Add the chicken and fish sauce and cook for 5 minutes, turning, until the chicken is lightly coloured."},{"text":"Pour in the water and bring to the boil, skimming off any foam. Turn down to a gentle simmer, cover and cook for 25 minutes."},{"text":"Add the papaya and simmer for 8 to 10 minutes, until tender and the chicken is cooked through (75°C next to the bone). If using zucchini, it only needs 4 minutes."},{"text":"Stir in the spinach until wilted and season with pepper and more fish sauce to taste. Serve in bowls with rice, extra fish sauce and lime."}],"notes":["Green papaya is sold at Asian grocers. Choko (chayote) is the other classic choice.","Moringa or chilli leaves are traditional; baby spinach is the easy supermarket swap.","Food safety: Cook chicken (and other poultry) until the thickest part reaches 75°C and the juices run clear, with no pink meat near the bone."],"source":"user","provenance":"ai-draft"}},{"slug":"pancit-bihon","title":"Pancit Bihon","cuisine":"filipino","meal_types":["dinner","lunch"],"diets":["no-dairy"],"difficulty":"easy","total_minutes":40,"recipe":{"id":"pancit-bihon","title":"Pancit Bihon","summary":"Filipino party noodles: thin rice noodles stir-fried with chicken and crunchy vegetables.","cuisine":"filipino","diets":["no-dairy"],"mealTypes":["dinner","lunch"],"difficulty":"easy","prepMinutes":20,"cookMinutes":20,"servings":4,"onePot":false,"ingredientGroups":[{"items":[{"item":"rice vermicelli","raw":"250g rice vermicelli","quantity":250,"unit":"g","ingredientId":"rice-vermicelli"},{"item":"neutral oil","raw":"2 tbsp neutral oil","quantity":2,"unit":"tbsp","ingredientId":"neutral-oil"},{"item":"chicken thigh fillets","raw":"400g chicken thigh fillets, thinly sliced","quantity":400,"unit":"g","ingredientId":"chicken-thigh","prep":"thinly sliced"},{"item":"brown onion","raw":"1 brown onion, sliced","quantity":1,"ingredientId":"brown-onion","prep":"sliced"},{"item":"garlic","raw":"4 garlic cloves, finely chopped","quantity":4,"unit":"clove","ingredientId":"garlic","prep":"finely chopped"},{"item":"carrot","raw":"1 carrot, cut into matchsticks","quantity":1,"ingredientId":"carrot","prep":"cut into matchsticks"},{"item":"green beans","raw":"150g green beans, sliced on an angle","quantity":150,"unit":"g","ingredientId":"green-beans","prep":"sliced on an angle"},{"item":"cabbage","raw":"1/4 cabbage, shredded","quantity":0.25,"ingredientId":"cabbage","prep":"shredded"},{"item":"chicken stock","raw":"375ml chicken stock","quantity":375,"unit":"ml","ingredientId":"chicken-stock"},{"item":"soy sauce","raw":"3 tbsp soy sauce","quantity":3,"unit":"tbsp","ingredientId":"soy-sauce"},{"item":"oyster sauce","raw":"1 tbsp oyster sauce","quantity":1,"unit":"tbsp","ingredientId":"oyster-sauce"},{"item":"black pepper","raw":"1/2 tsp black pepper","quantity":0.5,"unit":"tsp","ingredientId":"black-pepper"},{"item":"spring onions","raw":"3 spring onions, sliced","quantity":3,"ingredientId":"spring-onion","prep":"sliced"},{"item":"Lemon wedges","raw":"Lemon wedges, to serve","ingredientId":"lemon","prep":"to serve"}]}],"steps":[{"text":"Soak the noodles in warm water for 10 minutes until pliable, then drain."},{"text":"Heat the oil in a wok or very large frying pan over high heat. Stir-fry the chicken for 4 to 5 minutes until cooked through. Lift onto a plate."},{"text":"Add the onion and garlic and stir-fry for 2 minutes. Add the carrot and beans for 2 minutes, then the cabbage for 1 minute. Tip the vegetables onto the chicken."},{"text":"Pour the stock, soy sauce and oyster sauce into the wok and bring to the boil. Add the noodles and toss with tongs until they've absorbed the liquid, about 3 minutes."},{"text":"Return the chicken and vegetables, season with pepper and toss well. Scatter with spring onion and serve with lemon wedges to squeeze over."}],"notes":["Calamansi is the traditional squeeze. Lemon is the closest supermarket swap.","Pancit is served at birthdays for long life, so the noodles are never cut.","Food safety: Cook chicken and other poultry until the juices run clear and the thickest part reaches 75°C."],"source":"user","provenance":"ai-draft"}},{"slug":"chicken-tinga-tostadas","title":"Chicken Tinga Tostadas","cuisine":"mexican","meal_types":["dinner","lunch"],"diets":["no-gluten"],"difficulty":"easy","total_minutes":50,"recipe":{"id":"chicken-tinga-tostadas","title":"Chicken Tinga Tostadas","summary":"Smoky chipotle chicken piled on crisp baked tortillas with beans, avocado and feta.","cuisine":"mexican","diets":["no-gluten"],"mealTypes":["dinner","lunch"],"difficulty":"easy","prepMinutes":15,"cookMinutes":35,"servings":4,"onePot":false,"ingredientGroups":[{"title":"Tinga","items":[{"item":"neutral oil","raw":"1 tbsp neutral oil","quantity":1,"unit":"tbsp","ingredientId":"neutral-oil"},{"item":"brown onion","raw":"1 brown onion, thinly sliced","quantity":1,"ingredientId":"brown-onion","prep":"thinly sliced"},{"item":"garlic","raw":"3 garlic cloves, crushed","quantity":3,"unit":"clove","ingredientId":"garlic","prep":"crushed"},{"item":"chipotles in adobo","raw":"2 chipotles in adobo, chopped, plus 1 tbsp of the sauce","quantity":2,"ingredientId":"chipotle-in-adobo","prep":"chopped, plus 1 tbsp of the sauce"},{"item":"dried oregano","raw":"1 tsp dried oregano","quantity":1,"unit":"tsp","ingredientId":"dried-oregano"},{"item":"ground cumin","raw":"1/2 tsp ground cumin","quantity":0.5,"unit":"tsp","ingredientId":"ground-cumin"},{"item":"crushed tomatoes","raw":"400g tin crushed tomatoes","quantity":400,"unit":"g","ingredientId":"tinned-tomatoes","note":"tin"},{"item":"chicken stock","raw":"125ml chicken stock","quantity":125,"unit":"ml","ingredientId":"chicken-stock"},{"item":"chicken thigh fillets","raw":"600g chicken thigh fillets","quantity":600,"unit":"g","ingredientId":"chicken-thigh"},{"item":"salt","raw":"1/2 tsp salt","quantity":0.5,"unit":"tsp","ingredientId":"salt"}]},{"title":"Tostadas","items":[{"item":"small corn tortillas","raw":"12 small corn tortillas","quantity":12,"ingredientId":"corn-tortilla"},{"item":"neutral oil","raw":"2 tbsp neutral oil","quantity":2,"unit":"tbsp","ingredientId":"neutral-oil"},{"item":"black beans","raw":"400g tin black beans, drained and rinsed","quantity":400,"unit":"g","ingredientId":"black-beans","prep":"drained and rinsed","note":"tin"},{"item":"ground cumin","raw":"1/2 tsp ground cumin","quantity":0.5,"unit":"tsp","ingredientId":"ground-cumin"},{"item":"lime juice","raw":"1 tbsp lime juice","quantity":1,"unit":"tbsp","ingredientId":"lime"}]},{"title":"To top","items":[{"item":"shredded iceberg lettuce","raw":"2 cups shredded iceberg lettuce","quantity":2,"unit":"cup","ingredientId":"iceberg-lettuce"},{"item":"avocado","raw":"1 avocado, sliced","quantity":1,"ingredientId":"avocado","prep":"sliced"},{"item":"feta","raw":"80g feta, crumbled","quantity":80,"unit":"g","ingredientId":"feta","prep":"crumbled"},{"item":"sour cream","raw":"100g sour cream","quantity":100,"unit":"g","ingredientId":"sour-cream"},{"item":"coriander leaves","raw":"Handful of coriander leaves","quantity":1,"unit":"handful","ingredientId":"coriander"},{"item":"Lime wedges","raw":"Lime wedges","ingredientId":"lime"}]}],"steps":[{"text":"Heat the oil in a deep frying pan over medium heat. Cook the onion for 6 minutes until soft. Add the garlic, chipotles and their sauce, oregano and cumin for 1 minute."},{"text":"Add the tomatoes, stock, chicken and salt. Cover and simmer gently for 20 minutes, until the chicken is cooked through (75°C). Lift the chicken out, shred it with two forks, and return it to the sauce. Simmer uncovered for 5 minutes until thick and clinging."},{"text":"Meanwhile, heat the oven to 200°C (180°C fan-forced). Brush the tortillas lightly with oil on both sides, spread over two trays and bake for 8 to 10 minutes, turning once, until crisp and golden."},{"text":"Mash the beans with the cumin, lime juice and a pinch of salt, adding a splash of water to make it spreadable. Warm briefly in a small pan."},{"text":"Spread each tostada with beans, then top with chicken tinga, lettuce, avocado, feta, sour cream and coriander. Serve with lime wedges and eat with your hands."}],"notes":["The tinga keeps for 3 days in the fridge and is just as good in tacos, burritos or on rice.","Check the tortilla label if you need these gluten-free; some brands add wheat flour.","Food safety: Cook chicken (and other poultry) until the thickest part reaches 75°C and the juices run clear, with no pink meat near the bone."],"source":"user","provenance":"ai-draft"}},{"slug":"arroz-con-pollo","title":"Arroz con Pollo","cuisine":"latin-american","meal_types":["dinner"],"diets":["no-gluten","no-dairy"],"difficulty":"easy","total_minutes":65,"recipe":{"id":"arroz-con-pollo","title":"Arroz con Pollo","summary":"One-pan Latin American chicken and rice, golden with paprika and studded with peas and olives.","cuisine":"latin-american","diets":["no-gluten","no-dairy"],"mealTypes":["dinner"],"difficulty":"easy","prepMinutes":15,"cookMinutes":50,"servings":4,"onePot":true,"ingredientGroups":[{"items":[{"item":"chicken thigh","raw":"8 chicken thigh fillets (about 1kg)","quantity":8,"unit":"fillet","ingredientId":"chicken-thigh","note":"about 1kg"},{"item":"salt","raw":"1 1/2 tsp salt","quantity":1.5,"unit":"tsp","ingredientId":"salt"},{"item":"smoked paprika","raw":"1 tsp smoked paprika","quantity":1,"unit":"tsp","ingredientId":"smoked-paprika"},{"item":"ground cumin","raw":"1 tsp ground cumin","quantity":1,"unit":"tsp","ingredientId":"ground-cumin"},{"item":"olive oil","raw":"2 tbsp olive oil","quantity":2,"unit":"tbsp","ingredientId":"olive-oil"},{"item":"brown onion","raw":"1 brown onion, diced","quantity":1,"ingredientId":"brown-onion","prep":"diced"},{"item":"red capsicum","raw":"1 red capsicum, diced","quantity":1,"ingredientId":"capsicum","prep":"diced"},{"item":"garlic","raw":"4 garlic cloves, crushed","quantity":4,"unit":"clove","ingredientId":"garlic","prep":"crushed"},{"item":"dried oregano","raw":"1 tsp dried oregano","quantity":1,"unit":"tsp","ingredientId":"dried-oregano"},{"item":"ground turmeric","raw":"1/2 tsp ground turmeric","quantity":0.5,"unit":"tsp","ingredientId":"ground-turmeric"},{"item":"tomato paste","raw":"2 tbsp tomato paste","quantity":2,"unit":"tbsp","ingredientId":"tomato-paste"},{"item":"long-grain white rice","raw":"300g long-grain white rice, rinsed","quantity":300,"unit":"g","ingredientId":"white-rice","prep":"rinsed"},{"item":"chicken stock","raw":"750ml chicken stock","quantity":750,"unit":"ml","ingredientId":"chicken-stock"},{"item":"frozen peas","raw":"150g frozen peas","quantity":150,"unit":"g","ingredientId":"frozen-peas"},{"item":"green olives","raw":"60g green olives, halved","quantity":60,"unit":"g","ingredientId":"green-olive","prep":"halved"},{"item":"coriander leaves","raw":"Handful of coriander leaves, chopped","quantity":1,"unit":"handful","ingredientId":"coriander","prep":"chopped"},{"item":"Lime wedges","raw":"Lime wedges, to serve","ingredientId":"lime","prep":"to serve"}]}],"steps":[{"text":"Season the chicken with 1 tsp of the salt, the paprika and the cumin. Heat the oil in a large deep frying pan or casserole with a lid over medium-high heat and brown the chicken for 3 minutes each side. Lift onto a plate."},{"text":"Turn the heat to medium. Cook the onion and capsicum for 6 minutes until soft. Add the garlic, oregano and turmeric for 1 minute, then the tomato paste for 1 minute."},{"text":"Add the rice and stir for 1 minute to coat in the oil. Pour in the stock, add the remaining salt and bring to the boil."},{"text":"Nestle the chicken into the rice. Cover tightly, turn the heat to low and cook for 20 minutes, without lifting the lid."},{"text":"Scatter over the peas and olives, cover again and cook for 5 minutes more, until the rice is tender, the liquid absorbed and the chicken cooked through (75°C). Rest off the heat, covered, for 5 minutes."},{"text":"Fluff the rice with a fork, scatter with coriander and serve with lime wedges."}],"notes":["A pinch of saffron in the stock is lovely if you have it.","Check the stock label if you need this gluten-free.","Food safety: Cook chicken (and other poultry) until the thickest part reaches 75°C and the juices run clear, with no pink meat near the bone."],"source":"user","provenance":"ai-draft"}},{"slug":"toad-in-the-hole","title":"Toad in the Hole","cuisine":"british","meal_types":["dinner"],"diets":[],"difficulty":"medium","total_minutes":85,"recipe":{"id":"toad-in-the-hole","title":"Toad in the Hole","summary":"Pork sausages baked in a tall, crisp Yorkshire pudding batter, with a rich onion gravy.","cuisine":"british","diets":[],"mealTypes":["dinner"],"difficulty":"medium","prepMinutes":40,"cookMinutes":45,"servings":4,"onePot":false,"seasons":["autumn","winter"],"ingredientGroups":[{"title":"Batter","items":[{"item":"plain flour","raw":"140g plain flour","quantity":140,"unit":"g","ingredientId":"plain-flour"},{"item":"eggs","raw":"4 eggs","quantity":4,"ingredientId":"egg"},{"item":"milk","raw":"200ml milk","quantity":200,"unit":"ml","ingredientId":"milk"},{"item":"salt","raw":"1/2 tsp salt","quantity":0.5,"unit":"tsp","ingredientId":"salt"}]},{"title":"Sausages","items":[{"item":"thick pork sausages","raw":"8 thick pork sausages","quantity":8,"ingredientId":"pork-sausage"},{"item":"neutral oil","raw":"3 tbsp neutral oil (or beef dripping)","quantity":3,"unit":"tbsp","ingredientId":"neutral-oil","note":"or beef dripping"}]},{"title":"Onion gravy","items":[{"item":"butter","raw":"20g butter","quantity":20,"unit":"g","ingredientId":"butter"},{"item":"brown onions","raw":"2 brown onions, thinly sliced","quantity":2,"ingredientId":"brown-onion","prep":"thinly sliced"},{"item":"plain flour","raw":"1 tbsp plain flour","quantity":1,"unit":"tbsp","ingredientId":"plain-flour"},{"item":"beef stock","raw":"500ml beef stock","quantity":500,"unit":"ml","ingredientId":"beef-stock"},{"item":"Worcestershire sauce","raw":"1 tsp Worcestershire sauce","quantity":1,"unit":"tsp","ingredientId":"worcestershire-sauce"},{"item":"thyme","raw":"1 thyme sprig","quantity":1,"unit":"sprig","ingredientId":"thyme"}]},{"title":"To serve","items":[{"item":"green beans","raw":"200g green beans, trimmed and steamed","quantity":200,"unit":"g","ingredientId":"green-beans","prep":"trimmed and steamed"}]}],"steps":[{"text":"Whisk the flour, eggs, milk and salt to a smooth batter the thickness of pouring cream. Rest it for at least 30 minutes at room temperature."},{"text":"Heat the oven to 220°C (200°C fan-forced). Put the sausages and oil in a 20 x 30cm metal roasting tin and roast for 15 minutes, turning once, until browned."},{"text":"Working quickly, take the tin out and check the fat is smoking hot. Whisk the batter once more and pour it around the sausages; it should sizzle. Return to the oven straight away."},{"text":"Bake for 25 to 30 minutes, without opening the door, until the batter has risen high and is deep golden and crisp, and the sausages are cooked through (75°C in the centre)."},{"text":"Meanwhile, make the gravy: melt the butter in a saucepan over medium-low heat and cook the onions for 15 to 20 minutes, until soft and caramelised. Stir in the flour for 1 minute, then gradually whisk in the stock. Add the Worcestershire and thyme and simmer for 8 minutes until thickened."},{"text":"Cut the toad into portions and serve with plenty of onion gravy and green beans."}],"notes":["The two rules for a tall rise: smoking-hot fat in a metal tin, and no peeking for the first 20 minutes.","Use good butcher's sausages; they're the star.","Food safety: Raw and lightly cooked foods aren't recommended for pregnant women, young children, older people or anyone with a weakened immune system."],"source":"user","provenance":"ai-draft"}},{"slug":"chicken-paprikash","title":"Chicken Paprikash","cuisine":"central-european","meal_types":["dinner"],"diets":[],"difficulty":"easy","total_minutes":60,"recipe":{"id":"chicken-paprikash","title":"Chicken Paprikash","summary":"Hungarian chicken braised in a sweet paprika and capsicum sauce, finished with sour cream.","cuisine":"central-european","diets":[],"mealTypes":["dinner"],"difficulty":"easy","prepMinutes":15,"cookMinutes":45,"servings":4,"onePot":false,"seasons":["autumn","winter"],"ingredientGroups":[{"title":"Paprikash","items":[{"item":"chicken thigh fillets","raw":"800g chicken thigh fillets, cut into large pieces","quantity":800,"unit":"g","ingredientId":"chicken-thigh","prep":"cut into large pieces"},{"item":"salt","raw":"1 tsp salt","quantity":1,"unit":"tsp","ingredientId":"salt"},{"item":"neutral oil","raw":"2 tbsp neutral oil","quantity":2,"unit":"tbsp","ingredientId":"neutral-oil"},{"item":"brown onions","raw":"2 brown onions, finely diced","quantity":2,"ingredientId":"brown-onion","prep":"finely diced"},{"item":"red capsicum","raw":"1 red capsicum, diced","quantity":1,"ingredientId":"capsicum","prep":"diced"},{"item":"garlic","raw":"3 garlic cloves, crushed","quantity":3,"unit":"clove","ingredientId":"garlic","prep":"crushed"},{"item":"sweet paprika","raw":"2 tbsp sweet paprika","quantity":2,"unit":"tbsp","ingredientId":"paprika"},{"item":"smoked paprika","raw":"1/2 tsp smoked paprika","quantity":0.5,"unit":"tsp","ingredientId":"smoked-paprika"},{"item":"tomato paste","raw":"1 tbsp tomato paste","quantity":1,"unit":"tbsp","ingredientId":"tomato-paste"},{"item":"chicken stock","raw":"375ml chicken stock","quantity":375,"unit":"ml","ingredientId":"chicken-stock"},{"item":"sour cream","raw":"150g sour cream","quantity":150,"unit":"g","ingredientId":"sour-cream"},{"item":"plain flour","raw":"1 tbsp plain flour","quantity":1,"unit":"tbsp","ingredientId":"plain-flour"},{"item":"flat-leaf parsley","raw":"Handful of flat-leaf parsley, chopped","quantity":1,"unit":"handful","ingredientId":"parsley","prep":"chopped"}]},{"title":"To serve","items":[{"item":"wide egg noodles","raw":"300g wide egg noodles","quantity":300,"unit":"g","ingredientId":"egg-noodles"},{"item":"butter","raw":"20g butter","quantity":20,"unit":"g","ingredientId":"butter"}]}],"steps":[{"text":"Season the chicken with the salt. Heat the oil in a large deep frying pan or casserole over medium-high heat and brown the chicken in two batches, 3 minutes per batch. Lift onto a plate."},{"text":"Turn the heat to medium-low. Cook the onions for 10 minutes, stirring, until soft and golden. Add the capsicum and garlic for 3 minutes."},{"text":"Take the pan off the heat and stir in both paprikas; paprika burns and turns bitter over high heat. Stir in the tomato paste, then the stock, and return to the heat."},{"text":"Add the chicken and bring to a gentle simmer. Cover and cook for 20 minutes, until the chicken is cooked through and tender."},{"text":"Meanwhile, cook the noodles following the packet instructions until tender with a little bite. Drain and toss with the butter until melted and glossy."},{"text":"Whisk the sour cream and flour together in a bowl, then whisk in a ladle of the hot sauce. Stir it into the pan and simmer gently for 2 minutes until thickened; the flour stops the sour cream splitting. Scatter with parsley and serve over the buttered noodles."}],"notes":["Use fresh paprika. If yours has been in the cupboard for years, it'll taste of dust.","Mashed potato or rice are good in place of the noodles.","Food safety: Cook chicken and other poultry until the juices run clear and the thickest part reaches 75°C."],"source":"user","provenance":"ai-draft"}},{"slug":"nordic-fish-soup","title":"Nordic Fish Soup","cuisine":"scandinavian","meal_types":["dinner","lunch"],"diets":["pescatarian","no-gluten"],"difficulty":"easy","total_minutes":45,"recipe":{"id":"nordic-fish-soup","title":"Nordic Fish Soup","summary":"A creamy Scandinavian soup of white fish and salmon with potato, leek and lots of dill.","cuisine":"scandinavian","diets":["pescatarian","no-gluten"],"mealTypes":["dinner","lunch"],"difficulty":"easy","prepMinutes":15,"cookMinutes":30,"servings":4,"onePot":true,"seasons":["autumn","winter"],"ingredientGroups":[{"items":[{"item":"butter","raw":"30g butter","quantity":30,"unit":"g","ingredientId":"butter"},{"item":"leek","raw":"1 leek, white and pale green part, sliced","quantity":1,"ingredientId":"leek","prep":"white and pale green part, sliced"},{"item":"carrot","raw":"1 carrot, diced","quantity":1,"ingredientId":"carrot","prep":"diced"},{"item":"waxy potatoes","raw":"500g waxy potatoes, cut into 2cm cubes","quantity":500,"unit":"g","ingredientId":"waxy-potato","prep":"cut into 2cm cubes"},{"item":"bay","raw":"1 bay leaf","quantity":1,"unit":"leaf","ingredientId":"bay-leaf"},{"item":"fish stock","raw":"1L fish stock","quantity":1,"unit":"l","ingredientId":"fish-stock"},{"item":"cream","raw":"250ml cream","quantity":250,"unit":"ml","ingredientId":"cream"},{"item":"firm white fish fillets","raw":"400g firm white fish fillets, skinned and cut into 3cm chunks","quantity":400,"unit":"g","ingredientId":"white-fish","prep":"skinned and cut into 3cm chunks"},{"item":"skinless salmon fillet","raw":"250g skinless salmon fillet, cut into 3cm chunks","quantity":250,"unit":"g","ingredientId":"salmon","prep":"cut into 3cm chunks"},{"item":"dill","raw":"1/2 bunch dill, chopped","quantity":0.5,"unit":"bunch","ingredientId":"dill","prep":"chopped"},{"item":"lemon","raw":"Juice of 1/2 lemon","quantity":0.5,"ingredientId":"lemon","prep":"juiced"},{"item":"Salt","raw":"Salt","ingredientId":"salt"},{"item":"Ground white pepper","raw":"Ground white pepper","ingredientId":"white-pepper"}]},{"title":"To serve","items":[{"item":"Buttered rye bread","raw":"Buttered rye bread (optional)","ingredientId":"rye-bread","optional":true}]}],"steps":[{"text":"Melt the butter in a large pot over medium heat. Cook the leek and carrot for 6 minutes until soft but not coloured."},{"text":"Add the potatoes, bay leaf and stock. Bring to the boil, then simmer for 12 to 15 minutes, until the potatoes are just tender."},{"text":"Pour in the cream and bring back to a gentle simmer. Add the white fish and salmon and poach gently, without boiling, for 4 to 5 minutes, until just opaque and flaking."},{"text":"Remove the bay leaf. Stir in most of the dill and the lemon juice gently, so the fish doesn't break up, and season with salt and white pepper."},{"text":"Ladle into bowls, top with the rest of the dill and serve with buttered rye bread."}],"notes":["A few cooked prawns added at the end make it a feast.","Check the stock label if you need this gluten-free.","Food safety: Cook fish until it turns opaque and flakes easily, about 63°C in the thickest part."],"source":"user","provenance":"ai-draft"}},{"slug":"lamb-pumpkin-feta-salad","title":"Lamb, Pumpkin and Feta Salad","cuisine":"modern-australian","meal_types":["dinner","lunch"],"diets":["no-gluten"],"difficulty":"easy","total_minutes":50,"recipe":{"id":"lamb-pumpkin-feta-salad","title":"Lamb, Pumpkin and Feta Salad","summary":"Cumin-spiced lamb over roast pumpkin, rocket, feta and toasted seeds with a honey dressing.","cuisine":"modern-australian","diets":["no-gluten"],"mealTypes":["dinner","lunch"],"difficulty":"easy","prepMinutes":15,"cookMinutes":35,"servings":4,"onePot":false,"seasons":["autumn","winter"],"ingredientGroups":[{"title":"Lamb and pumpkin","items":[{"item":"butternut pumpkin","raw":"800g butternut pumpkin, peeled and cut into 2cm wedges","quantity":800,"unit":"g","ingredientId":"pumpkin","prep":"peeled and cut into 2cm wedges"},{"item":"red onion","raw":"1 red onion, cut into wedges","quantity":1,"ingredientId":"red-onion","prep":"cut into wedges"},{"item":"olive oil","raw":"3 tbsp olive oil","quantity":3,"unit":"tbsp","ingredientId":"olive-oil"},{"item":"salt","raw":"1 tsp salt","quantity":1,"unit":"tsp","ingredientId":"salt"},{"item":"lamb leg steaks","raw":"600g lamb leg steaks","quantity":600,"unit":"g","ingredientId":"lamb-leg"},{"item":"ground cumin","raw":"2 tsp ground cumin","quantity":2,"unit":"tsp","ingredientId":"ground-cumin"}]},{"title":"Dressing","items":[{"item":"extra virgin olive oil","raw":"3 tbsp extra virgin olive oil","quantity":3,"unit":"tbsp","ingredientId":"olive-oil"},{"item":"balsamic vinegar","raw":"1 tbsp balsamic vinegar","quantity":1,"unit":"tbsp","ingredientId":"balsamic-vinegar"},{"item":"honey","raw":"1 tsp honey","quantity":1,"unit":"tsp","ingredientId":"honey"},{"item":"Dijon mustard","raw":"1 tsp Dijon mustard","quantity":1,"unit":"tsp","ingredientId":"dijon-mustard"}]},{"title":"Salad","items":[{"item":"rocket","raw":"120g rocket","quantity":120,"unit":"g","ingredientId":"rocket"},{"item":"feta","raw":"100g feta, crumbled","quantity":100,"unit":"g","ingredientId":"feta","prep":"crumbled"},{"item":"pepitas","raw":"2 tbsp pepitas, toasted","quantity":2,"unit":"tbsp","ingredientId":"pumpkin-seeds","prep":"toasted"},{"item":"mint leaves","raw":"Handful of mint leaves","quantity":1,"unit":"handful","ingredientId":"mint"}]}],"steps":[{"text":"Heat the oven to 220°C (200°C fan-forced). Toss the pumpkin and onion with 2 tbsp of the oil and half the salt on a lined tray. Roast for 30 to 35 minutes, turning once, until tender and caramelised at the edges."},{"text":"Rub the lamb with the remaining oil and salt and the cumin. Leave at room temperature while the pumpkin roasts."},{"text":"Whisk the dressing ingredients together with a pinch of salt."},{"text":"Heat a frying pan or chargrill over high heat. Cook the lamb for 3 to 4 minutes each side for medium. Rest on a board for 5 minutes, then slice thickly."},{"text":"Toss the rocket with half the dressing and spread over a platter. Top with the warm pumpkin and onion, the lamb and any resting juices, the feta, pepitas and mint. Drizzle with the rest of the dressing."}],"notes":["Lamb backstrap is a tender, quick-cooking swap for the leg steaks; cook it 3 minutes each side.","Leftovers make a great packed lunch with a handful of cooked grains through it.","Food safety: Cook whole cuts of beef, lamb and pork to at least 63°C in the thickest part, then rest for 3 minutes; cook pork and any rolled or stuffed cuts until the juices run clear."],"source":"user","provenance":"ai-draft"}},{"slug":"philly-cheesesteak","title":"Philly Cheesesteak","cuisine":"american","meal_types":["dinner","lunch"],"diets":[],"difficulty":"easy","total_minutes":45,"recipe":{"id":"philly-cheesesteak","title":"Philly Cheesesteak","summary":"Thin-sliced steak, soft onions and capsicum under melted cheese, stuffed into a long roll.","cuisine":"american","diets":[],"mealTypes":["dinner","lunch"],"difficulty":"easy","prepMinutes":25,"cookMinutes":20,"servings":4,"onePot":false,"ingredientGroups":[{"items":[{"item":"scotch fillet steak","raw":"600g scotch fillet steak","quantity":600,"unit":"g","ingredientId":"beef-rib-eye"},{"item":"neutral oil","raw":"2 tbsp neutral oil","quantity":2,"unit":"tbsp","ingredientId":"neutral-oil"},{"item":"brown onions","raw":"2 brown onions, thinly sliced","quantity":2,"ingredientId":"brown-onion","prep":"thinly sliced"},{"item":"green capsicum","raw":"1 green capsicum, thinly sliced","quantity":1,"ingredientId":"green-capsicum","prep":"thinly sliced"},{"item":"salt","raw":"1 tsp salt","quantity":1,"unit":"tsp","ingredientId":"salt"},{"item":"black pepper","raw":"1/2 tsp black pepper","quantity":0.5,"unit":"tsp","ingredientId":"black-pepper"},{"item":"Worcestershire sauce","raw":"1 tsp Worcestershire sauce","quantity":1,"unit":"tsp","ingredientId":"worcestershire-sauce"},{"item":"Swiss cheese","raw":"8 slices Swiss cheese (or provolone)","quantity":8,"unit":"slice","ingredientId":"swiss-cheese","note":"or provolone"},{"item":"long sub rolls","raw":"4 long sub rolls, split","quantity":4,"ingredientId":"bread-roll","prep":"split"},{"item":"butter","raw":"20g butter, softened","quantity":20,"unit":"g","ingredientId":"butter","prep":"softened"}]}],"steps":[{"text":"Put the steak in the freezer for 20 minutes, then slice it as thinly as you can across the grain."},{"text":"Heat 1 tbsp oil in a large frying pan over medium heat. Cook the onions and capsicum with a pinch of the salt for 10 minutes, stirring, until soft and golden. Tip onto a plate."},{"text":"Turn the heat to high and add the rest of the oil. Add the steak in a single layer, season with the remaining salt and the pepper, and cook for 2 to 3 minutes, turning and chopping it with the edge of a spatula, until browned. Stir in the Worcestershire and return the onions and capsicum."},{"text":"Divide the mixture into four long piles in the pan, lay two slices of cheese over each and cover with a lid for 1 minute to melt."},{"text":"Meanwhile, butter the cut sides of the rolls and toast them in a hot pan or under the grill until golden and crisp at the edges. Slide a spatula under each pile of steak and cheese and tip it into a roll. Serve hot, while the cheese is still melted."}],"notes":["Thin slicing is everything here. Many butchers will slice the steak for you.","Mozzarella or tasty cheese melt well if you can't find provolone.","Food safety: Steaks and roasting cuts of beef or lamb can be served pink: about 60°C in the centre is medium-rare, 70°C is well done."],"source":"user","provenance":"ai-draft"}},{"slug":"chicken-saltimbocca","title":"Chicken Saltimbocca","cuisine":"italian","meal_types":["dinner"],"diets":[],"difficulty":"easy","total_minutes":30,"recipe":{"id":"chicken-saltimbocca","title":"Chicken Saltimbocca","summary":"Thin chicken escalopes wrapped in prosciutto and sage, pan-fried and finished with a buttery white wine sauce.","cuisine":"italian","diets":[],"mealTypes":["dinner"],"difficulty":"easy","prepMinutes":15,"cookMinutes":15,"servings":4,"onePot":false,"ingredientGroups":[{"title":"Chicken","items":[{"item":"large chicken breast","raw":"2 large chicken breast fillets (about 600g)","quantity":2,"unit":"fillet","ingredientId":"chicken-breast","note":"about 600g"},{"item":"salt","raw":"1/2 tsp salt","quantity":0.5,"unit":"tsp","ingredientId":"salt"},{"item":"black pepper","raw":"1/4 tsp black pepper","quantity":0.25,"unit":"tsp","ingredientId":"black-pepper"},{"item":"sage","raw":"8 sage leaves","quantity":8,"unit":"leaf","ingredientId":"sage"},{"item":"prosciutto","raw":"8 slices prosciutto","quantity":8,"unit":"slice","ingredientId":"prosciutto"},{"item":"plain flour","raw":"2 tbsp plain flour","quantity":2,"unit":"tbsp","ingredientId":"plain-flour"},{"item":"olive oil","raw":"2 tbsp olive oil","quantity":2,"unit":"tbsp","ingredientId":"olive-oil"}]},{"title":"Sauce","items":[{"item":"dry white wine","raw":"125ml dry white wine","quantity":125,"unit":"ml","ingredientId":"white-wine"},{"item":"chicken stock","raw":"125ml chicken stock","quantity":125,"unit":"ml","ingredientId":"chicken-stock"},{"item":"cold butter","raw":"30g cold butter, diced","quantity":30,"unit":"g","ingredientId":"butter","prep":"diced"},{"item":"lemon","raw":"Juice of 1/2 lemon","quantity":0.5,"ingredientId":"lemon","prep":"juiced"}]},{"title":"To serve","items":[{"item":"rocket","raw":"120g rocket","quantity":120,"unit":"g","ingredientId":"rocket"},{"item":"lemon","raw":"1 lemon, cut into wedges","quantity":1,"ingredientId":"lemon","prep":"cut into wedges"}]}],"steps":[{"text":"Slice each chicken breast in half horizontally to make 4 thin fillets, then cut each in half again so you have 8 pieces. Lay them between two sheets of baking paper and flatten with a rolling pin to about 1cm thick."},{"text":"Season the chicken lightly with salt and pepper (go easy on salt, as the prosciutto is salty). Lay a sage leaf on each piece and wrap a slice of prosciutto around it, pressing so it sticks. Dust both sides with flour and shake off the excess."},{"text":"Heat the oil in a large frying pan over medium-high heat. Fry the chicken prosciutto-side down first for 3 minutes, until crisp, then turn and cook for 2 to 3 minutes more, until cooked through (75°C in the thickest part). Cook in two batches if needed and keep warm on a plate."},{"text":"Pour the wine into the pan and let it bubble for 1 minute, scraping up the browned bits. Add the stock and simmer for 2 to 3 minutes until reduced by half. Take the pan off the heat and swirl in the butter a few pieces at a time until glossy, then add the lemon juice."},{"text":"Return the chicken and any juices to the pan to coat. Serve with the sauce spooned over, rocket and lemon wedges."}],"notes":["Veal escalopes are the classic version and cook in about the same time; veal can be served slightly pink.","Mashed potato or crusty bread is good for the sauce.","Food safety: Cook chicken (and other poultry) until the thickest part reaches 75°C and the juices run clear, with no pink meat near the bone."],"source":"user","provenance":"ai-draft"}}]$q$::jsonb)), dn as (select r, row_number() over (partition by r->>'cuisine' order by r->>'slug') rn from d), cand as (select c.id, x.cuisine, row_number() over (partition by x.cuisine order by c.recipe_count, c.handle)-1 ix, count(*) over (partition by x.cuisine) cnt from public.cooks c join (select distinct cook_id, cuisine from public.published_recipes where status='published') x on x.cook_id=c.id where c.kind='person'), ins as (insert into public.published_recipes (cook_id,slug,title,cuisine,meal_types,diets,difficulty,total_minutes,recipe,review,status) select coalesce((select cd.id from cand cd where cd.cuisine=dn.r->>'cuisine' and cd.ix=(dn.rn-1)%cd.cnt),(select id from public.cooks where kind='official' limit 1)), dn.r->>'slug', dn.r->>'title', dn.r->>'cuisine', array(select jsonb_array_elements_text(dn.r->'meal_types')), array(select jsonb_array_elements_text(dn.r->'diets')), dn.r->>'difficulty', (dn.r->>'total_minutes')::int, jsonb_set(dn.r->'recipe','{notes}',coalesce((select jsonb_agg(n) from jsonb_array_elements(dn.r->'recipe'->'notes') n where btrim(n#>>'{}') <> 'Food safety:'),'[]'::jsonb)), 'auto-checked','published' from dn where not exists (select 1 from public.published_recipes q where q.slug=dn.r->>'slug') on conflict do nothing returning id) select (select count(*) from d) expected, (select count(*) from ins) inserted;